export type Project = {
  name: string;
  description: string;
  url: string;
  year?: number;
  selected?: boolean;
  /** Rank among selected Projects on Home (ascending). */
  homeRank?: number;
};

/** Artifact milestone for AI Activity — real shipped repos only. */
export type ActivityMilestone = {
  name: string;
  year: number;
  outcome: string;
  url: string;
};

const PROJECTS: readonly Project[] = [
  {
    name: "GridFall",
    description: "Tetris in your terminal.",
    url: "https://github.com/Dhruv2mars/GridFall",
    year: 2025,
    selected: true,
    homeRank: 5,
  },
  {
    name: "Project-r",
    description: "Local AI tutor in your IDE (Gemma 3n).",
    url: "https://github.com/Dhruv2mars/project-r",
    year: 2025,
    selected: true,
    homeRank: 1,
  },
  {
    name: "Cinemasketch",
    description: "AI storyboards from a text prompt (NVIDIA).",
    url: "https://github.com/Dhruv2mars/cinemasketch",
    year: 2025,
    selected: true,
    homeRank: 4,
  },
  {
    name: "SuperChant",
    description: "Android mala with volume-button mantra counting.",
    url: "https://github.com/Dhruv2mars/superchant",
    year: 2026,
  },
  {
    name: "Detox",
    description: "Privacy-first Android app blocker.",
    url: "https://github.com/Dhruv2mars/detox",
    year: 2026,
  },
  {
    name: "Offdex",
    description: "Local-first Codex on phone, web, and bridge.",
    url: "https://github.com/Dhruv2mars/offdex",
    year: 2026,
    selected: true,
    homeRank: 2,
  },
  {
    name: "Gunmetal",
    description: "Local OpenAI-compatible API for your providers.",
    url: "https://github.com/Dhruv2mars/gunmetal",
    year: 2026,
    selected: true,
    homeRank: 3,
  },
  {
    name: "MDV",
    description: "Terminal Markdown editor with live preview.",
    url: "https://github.com/Dhruv2mars/mdv",
    year: 2026,
  },
];

export const PROJECT_NAMES = PROJECTS.map((p) => p.name);

/** Full Projects index in stable editorial order. */
export function getProjects(): readonly Project[] {
  return PROJECTS;
}

/** Home selected Projects, ordered by homeRank. */
export function getSelectedProjects(): readonly Project[] {
  return PROJECTS.filter((p) => p.selected)
    .slice()
    .sort((a, b) => (a.homeRank ?? 0) - (b.homeRank ?? 0));
}

/**
 * Artifact-linked milestones for the AI Activity chapter.
 * Curated from real repos (includes non-selected MDV) — not a Selected Projects clone.
 */
const ACTIVITY_MILESTONE_NAMES = [
  "Project-r",
  "Cinemasketch",
  "Offdex",
  "Gunmetal",
  "MDV",
] as const;

export function getActivityMilestones(): readonly ActivityMilestone[] {
  const byName = new Map(PROJECTS.map((p) => [p.name, p]));
  return ACTIVITY_MILESTONE_NAMES.flatMap((name) => {
    const p = byName.get(name);
    if (!p || p.year === undefined) return [];
    return [
      {
        name: p.name,
        year: p.year,
        outcome: p.description,
        url: p.url,
      },
    ];
  });
}

/** Hostname only — no path truncation ambiguity in the catalog rail. */
export function projectHostLabel(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/** @deprecated Prefer getProjects() — kept for any transitional imports. */
export const projects = PROJECTS;

